PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_version(version INTEGER PRIMARY KEY CHECK(version=1));
INSERT OR IGNORE INTO schema_version VALUES(1);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, login TEXT UNIQUE NOT NULL, name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('rh','employee')), password TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, must_change INTEGER NOT NULL DEFAULT 1, fictitious INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),csrf TEXT NOT NULL,expires REAL NOT NULL,last_seen REAL NOT NULL);
CREATE TABLE IF NOT EXISTS attempts(key TEXT PRIMARY KEY,count INTEGER NOT NULL,until REAL NOT NULL);
CREATE TABLE IF NOT EXISTS categories(id TEXT PRIMARY KEY,name TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS batches(id TEXT PRIMARY KEY,title TEXT NOT NULL,category TEXT NOT NULL REFERENCES categories(id),period TEXT NOT NULL,due TEXT,required INTEGER NOT NULL CHECK(required IN(0,1)),state TEXT NOT NULL CHECK(state IN('draft','released')),source TEXT NOT NULL,source_hash TEXT NOT NULL,page_count INTEGER NOT NULL,created TEXT NOT NULL,fictitious INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS items(id TEXT PRIMARY KEY,batch_id TEXT NOT NULL REFERENCES batches(id),user_id TEXT NOT NULL REFERENCES users(id),position INTEGER NOT NULL,pages TEXT NOT NULL,fields TEXT NOT NULL,UNIQUE(batch_id,user_id));
CREATE TABLE IF NOT EXISTS documents(id TEXT PRIMARY KEY,item_id TEXT NOT NULL REFERENCES items(id),version INTEGER NOT NULL,previous TEXT REFERENCES documents(id),status TEXT NOT NULL CHECK(status IN('pending','viewed','review','signed','available','superseded')),file TEXT NOT NULL,hash TEXT NOT NULL,fields TEXT NOT NULL,page_count INTEGER NOT NULL,signed_file TEXT,signed_hash TEXT,signed_at TEXT,created TEXT NOT NULL,UNIQUE(item_id,version),CHECK(status!='signed' OR (signed_file IS NOT NULL AND signed_hash IS NOT NULL AND signed_at IS NOT NULL)));
CREATE TABLE IF NOT EXISTS evidence(id TEXT PRIMARY KEY,document_id TEXT UNIQUE NOT NULL REFERENCES documents(id),user_id TEXT NOT NULL REFERENCES users(id),request_key TEXT NOT NULL UNIQUE,time TEXT NOT NULL,original_hash TEXT NOT NULL,final_hash TEXT NOT NULL,consent TEXT NOT NULL,strokes TEXT NOT NULL,agent TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS issues(id TEXT PRIMARY KEY,document_id TEXT NOT NULL REFERENCES documents(id),user_id TEXT NOT NULL REFERENCES users(id),message TEXT NOT NULL,response TEXT,created TEXT NOT NULL,resolved TEXT,prior TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY,user_id TEXT,action TEXT NOT NULL,target TEXT,time TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS immutable_signed BEFORE UPDATE ON documents WHEN OLD.signed_file IS NOT NULL AND (NEW.file!=OLD.file OR NEW.hash!=OLD.hash OR NEW.signed_file IS NOT OLD.signed_file OR NEW.signed_hash IS NOT OLD.signed_hash OR NEW.signed_at IS NOT OLD.signed_at OR NEW.fields!=OLD.fields OR NEW.item_id!=OLD.item_id OR NEW.version!=OLD.version OR NEW.status NOT IN('signed','superseded')) BEGIN SELECT RAISE(ABORT,'signed document immutable'); END;
CREATE TRIGGER IF NOT EXISTS no_delete_signed BEFORE DELETE ON documents WHEN OLD.signed_file IS NOT NULL BEGIN SELECT RAISE(ABORT,'signed document immutable'); END;
CREATE TRIGGER IF NOT EXISTS immutable_evidence BEFORE UPDATE ON evidence BEGIN SELECT RAISE(ABORT,'evidence immutable'); END;
CREATE TRIGGER IF NOT EXISTS no_delete_evidence BEFORE DELETE ON evidence BEGIN SELECT RAISE(ABORT,'evidence immutable'); END;
